package cn.lili.modules.community.p0.stage3;
import cn.lili.modules.community.p0.support.*;import org.junit.jupiter.api.Test;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.SimpleTransactionStatus;import java.time.*;import static cn.lili.modules.community.p0.support.Stage1Json.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.junit.jupiter.api.Assertions.*;
class Stage3MessagesTest {
 @Test void deliveryFailureRollsBackProjectionThenSchedulesRetryWithoutTouchingOrder(){var db=mock(Stage1Db.class);var manager=mock(PlatformTransactionManager.class);when(manager.getTransaction(any())).thenAnswer(i->new SimpleTransactionStatus());var orders=mock(Stage3Orders.class);when(db.one(anyString(),any(Object[].class))).thenReturn(map("id","1","event_type","READY","member_id","2","store_id","3","order_id","4"));when(db.id()).thenReturn("5");when(db.update(anyString(),any(Object[].class))).thenAnswer(i->{if(i.<String>getArgument(0).startsWith("INSERT INTO li_store_message"))throw new IllegalStateException("UNIT_ONLY_PROJECTION_FAILURE");return 1;});var service=new Stage3Messages(db,mock(Stage1Context.class),mock(Stage3Authorization.class),orders,Clock.fixed(Instant.parse("2026-10-31T00:00:00Z"),ZoneOffset.UTC),manager);
 assertFalse(service.deliverOne());verify(manager).rollback(any());verify(manager).commit(any());verify(db).update(contains("last_reason='DELIVERY_RETRY'"),any(Object[].class));verifyNoInteractions(orders);assertTrue(mockingDetails(db).getInvocations().stream().filter(i->i.getMethod().getName().equals("update")).map(i->i.<String>getArgument(0)).noneMatch(sql->sql.matches("(?is).*(UPDATE li_order |UPDATE li_p0_order_snapshot|inventory|payment).*")));}
 @Test void alreadyProjectedEventDoesNotCreateAnotherMessage(){var db=mock(Stage1Db.class);var manager=mock(PlatformTransactionManager.class);when(manager.getTransaction(any())).thenAnswer(i->new SimpleTransactionStatus());when(db.one(anyString(),any(Object[].class))).thenReturn(map("id","1","event_type","COMPLETED","member_id","2","store_id","3","order_id","4"));when(db.count(anyString(),any(Object[].class))).thenReturn(1L);var service=new Stage3Messages(db,mock(Stage1Context.class),mock(Stage3Authorization.class),mock(Stage3Orders.class),Clock.systemUTC(),manager);assertTrue(service.deliverOne());assertTrue(mockingDetails(db).getInvocations().stream().filter(i->i.getMethod().getName().equals("update")).noneMatch(i->i.<String>getArgument(0).startsWith("INSERT")));}
}
